import { useState, useEffect } from "react";

const useFetch = (url) => {
   const [data, setData] = useState([]);
   const [error, setError] = useState(null);
   const [loading, setLoading] = useState(false);

   useEffect(() => {
      const fetchData = async () => {
         setLoading(true);
         setError(null); // Reset lỗi mỗi lần gọi mới

         try {
            const token = localStorage.getItem('token');

            // Kiểm tra Token trước khi gửi
            if (!token) {
               setLoading(false);
               return setError("Vui lòng đăng nhập để tiếp tục!");
            }

            const res = await fetch(url, {
               method: 'GET',
               headers: {
                  'Authorization': `Bearer ${token}`,
                  'Content-Type': 'application/json'
               }
            });

            const result = await res.json();

            // QUAN TRỌNG: Nếu res không ok, phải return ngay để tránh setData sai
            if (!res.ok) {
               setLoading(false);
               return setError(result.message || 'Bạn không có quyền truy cập!');
            }

            setData(result.data || []);
            setLoading(false);
         } catch (err) {
            setError("Lỗi kết nối Server!");
            setLoading(false);
         }
      };

      fetchData();
   }, [url]);

   return { data, error, loading };
};

export default useFetch;
